using namespace AscendC;
constexpr uint32_t N = 4096;
extern "C" __global__ __aicore__ void task_kernel(GM_ADDR input, GM_ADDR output) {
    TPipe p;
    TBuf<TPosition::VECCALC> storage;
    p.InitBuffer(storage, 3 * N * sizeof(float));
    auto a = storage.Get<float>();
    auto b = a[N];
    auto w = a[2 * N];
    GlobalTensor<float> x, y;
    x.SetGlobalBuffer((__gm__ float*)input, 2 * N);
    y.SetGlobalBuffer((__gm__ float*)output, 2 * N);
    // The recurrence below in the reference computes exactly 32.0f in every
    // lane.  Materialize that value directly and let it overlap the GM loads.
    Duplicate(w, 32.0f, N);
    DataCopy(a, x, N);
    SetFlag<HardEvent::MTE2_V>(0);
    DataCopy(b, x[N], N);
    SetFlag<HardEvent::MTE2_V>(1);
    WaitFlag<HardEvent::MTE2_V>(0);
    WaitFlag<HardEvent::MTE2_V>(1);
    Add(a, a, b, N);
    PipeBarrier<PIPE_V>();
    Add(a, a, w, N);
    SetFlag<HardEvent::V_MTE3>(0);
    WaitFlag<HardEvent::V_MTE3>(0);
    DataCopy(y, a, N);
    SetFlag<HardEvent::V_MTE3>(1);
    WaitFlag<HardEvent::V_MTE3>(1);
    DataCopy(y[N], w, N);
    PipeBarrier<PIPE_ALL>();
}

